<https://example.org/openevidence/questions/q_prostate_cancer_efficacy> a holon:ClinicalQuestionHolon ;
    oe:questionText "How effective is pembrolizumab compared with other agents for Prostate Cancer?"^^xsd:string ;
    oe:answerText "There is an unmet need for a tool that could predict early favorable prostate-specific antigen (PSA) response in metastatic hormone sensitive prostate cancer (mHSPC) patients receiving androgen receptor pathway inhibitor (ARPI). Here, we train and validate a multivariable logistic regression model to predict early favorable PSA response (≤0.2 ng/mL by 6 months) in these patients."^^xsd:string ;
    holon:hasInteriorGraph <https://example.org/openevidence/questions/q_prostate_cancer_efficacy-int> ;
    holon:hasBoundaryGraph <https://example.org/openevidence/questions/q_prostate_cancer_efficacy-bou> ;
    holon:hasProjectionGraph <https://example.org/openevidence/questions/q_prostate_cancer_efficacy-pro> ;
    holon:hasContextGraph <https://example.org/openevidence/questions/q_prostate_cancer_efficacy-con> .

<https://example.org/openevidence/drugs/pembrolizumab> oe:treats <https://example.org/openevidence/diseases/prostate_cancer> .
<https://example.org/openevidence/generated/ev_q_prostate_cancer_efficacy_0> a holon:EvidenceAssertion ;
    rdf:reifies <https://example.org/openevidence/generated/ev_q_prostate_cancer_efficacy_0-tt> ;
    holon:confidence "0.90"^^xsd:decimal ;
    holon:evidenceLevel "Level-1B" ;
    holon:assessedBy <https://example.org/openevidence/questions/openevidence_ai> ;
    holon:recordedOn "2026-12-31"^^xsd:date ;
    oe:cites <https://example.org/openevidence/sources/41402322> ;
    holon:inHolon <https://example.org/openevidence/questions/q_prostate_cancer_efficacy> ;
    oe:effectiveness "effective" .
